    )

    private fun appendNotesExtendedPages(plan: PcSheetPdfRenderPlan) {
        val allRows = v2NativeNoteRows(
            plan = plan,
            rowsPerColumn = NOTES_COLUMN_CAPACITY,
            wrapIdentity = { text ->
                wrapByWidth(
                    resources.firaSemibold,
                    text,
                    9.25f,
                    NOTES_NATIVE_TEXT_WIDTH,
                )
            },
            wrapBody = { text ->
                wrapByWidth(
                    resources.fira,
                    text,
                    9.25f,
                    NOTES_NATIVE_TEXT_WIDTH,
                )
            },
        )
        val overflow = allRows.drop(BASE_V2_NOTES_CAPACITY)
        if (overflow.isEmpty()) return

        overflow.chunked(NOTES_CONTINUATION_CAPACITY).forEachIndexed { pageIndex, rows ->
            val page = PDPage(PDRectangle(W, H))
            document.addPage(page)
            renderNotesContinuationPage(page, rows, pageIndex)
        }
    }

    private fun renderNotesContinuationPage(
        page: PDPage,
        rows: List<V2NativeNoteRow>,
        pageIndex: Int,
    ) {
        val layerPrefix = if (pageIndex == 0) "V2X NOTES" else "V2X NOTES ${pageIndex + 1}"
        appendLayer(page, "$layerPrefix - STRUCTURE") { s ->
            s.drawForm(resources.forms[4])
        }
        appendLayer(page, "$layerPrefix - CLEANUP") { }
        appendLayer(page, "$layerPrefix - LABELS") { }
        appendLayer(page, "$layerPrefix - VALUES") { s ->
            rows.forEachIndexed { index, row ->
                val columnIndex = index / NOTES_COLUMN_CAPACITY
                val rowIndex = index % NOTES_COLUMN_CAPACITY
                val rule = if (columnIndex == 0) {
                    Rule(14f, 302.5f, 104f + rowIndex * 17f)
                } else {
                    Rule(309f, 597.5f, 104f + rowIndex * 17f)
                }
                when (row.style) {
                    V2NativeNoteRowStyle.IDENTITY -> textAboveRule(
                        s,
                        resources.firaSemibold,
                        rule,
                        row.text,
                        9.25f,
                        8.0f,
                        2.8f,
                    )
                    V2NativeNoteRowStyle.BODY -> textAboveRule(
                        s,
                        resources.fira,
                        rule,
                        row.text,
                        9.25f,
                        8.5f,
                        2.8f,
                    )
                    V2NativeNoteRowStyle.SPACER -> Unit
                }
            }
        }
        appendLayer(page, "$layerPrefix - MARKERS") { }
    }

    private fun wrapForRulesByChars(text: String, maxChars: Int): List<String> {
        val paragraphs = text
            .replace("\r\n", "\n")
            .split(Regex("\\n+"))
            .map { it.trim() }
            .filter { it.isNotEmpty() }
        val result = mutableListOf<String>()
        paragraphs.forEach { paragraph ->
            var current = ""
            paragraph.split(Regex("\\s+")).forEach { word ->
                val candidate = if (current.isEmpty()) word else "$current $word"
                if (candidate.length <= maxChars || current.isEmpty()) {
                    current = candidate
                } else {
                    result += current
                    current = word
                }
            }
            if (current.isNotEmpty()) result += current
        }
        return result
    }

        private fun featureEntry(
        s: PDFormContentStream,
        x: Float,
        firstRuleTop: Float,
        width: Float,
        trait: io.github.mrsimkin.dndcustomaid.shared.character.CharacterTrait,
    ): Float {
        var ruleTop = firstRuleTop
        fun nextRule(): Float = ruleTop.also { ruleTop += 17f }

        textAboveRule(
            s, resources.firaSemibold,
            Rule(x + 4f, x + width - 4f, nextRule()),
            trait.name, 9.0f, 7.4f, 2.7f,
        )

        val meta = listOf(
            traitTypeLabel(trait.type),
            trait.source.trim(),
            trait.activation?.let(::activationLabel).orEmpty(),
        ).filter { it.isNotEmpty() }.joinToString(" · ")
        if (meta.isNotEmpty()) {
            textAboveRule(
                s, resources.fira,
                Rule(x + 4f, x + width - 4f, nextRule()),
                meta, 7.3f, 6.2f, 2.5f,
            )
        }

        val uses = trait.maxUses?.let { max ->
            val current = (max - trait.spentUses).coerceIn(0, max)
            buildString {
                append("Usos: ").append(current).append(" / ").append(max)
                trait.recovery?.takeIf { it.isNotBlank() }?.let { append(" · ").append(it) }
            }
        } ?: trait.recovery?.takeIf { it.isNotBlank() }

        uses?.let {
            textAboveRule(
                s, resources.fira,
                Rule(x + 4f, x + width - 4f, nextRule()),
                it, 7.3f, 6.2f, 2.5f,
            )
        }

        featureDescriptionLines(trait, width - 8f)
            .take(FEATURE_DESCRIPTION_LINES)
            .forEach { line ->
                textAboveRule(
                    s, resources.fira,
                    Rule(x + 4f, x + width - 4f, nextRule()),
                    line, 7.4f, 6.2f, 2.5f,
                )
            }
        return ruleTop
    }

    private fun featureDescriptionLines(
        trait: io.github.mrsimkin.dndcustomaid.shared.character.CharacterTrait,
        width: Float,
    ): List<String> {
        val description = listOf(
            trait.description.trim(),
            trait.notes.orEmpty().trim(),
        ).filter { it.isNotEmpty() }.joinToString(" · ")
        return if (description.isEmpty()) emptyList()
        else wrapByWidth(resources.fira, description, 7.4f, width)
    }

